INSERT INTO `about_page_content` (`id`, `section_type`, `title`, `subtitle`, `description`, `image`, `icon_svg`, `link`, `page_badge_text`, `page_target_number`, `page_suffix`, `page_button_text`, `page_tag`, `page_color_scheme`, `page_year`, `page_card_color_class`, `page_rating`, `page_countries`, `page_pin_codes`, `display_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'Connecting People, Packages, <span class=\"moving-gradient-text\">  and Places.</span>', NULL, 'Since 1997, United Worldwide Couriers has been the bridge between modern B2B enterprises and their customers worldwide. With operations spanning across India and international markets, we foresee, resolve, and provide solutions for air freight, e-commerce logistics, warehousing, B2B shipping, marketplace integration, dropshipping, and more. Every shipment is supported by a team of professionals that makes us a trusted name and has earned us a reputation. Whether you\'re a startup shipping your first order or a multinational corporation managing complex supply chains, we bring the same commitment to excellence, transparency, and customer care on board.', 'website_images/1785303613_1778152300_1778151966_about-united.webp', NULL, NULL, 'About Us', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-07-29 05:40:13'),
(2, 'stat', 'Countries Global Reach', NULL, NULL, NULL, NULL, NULL, NULL, '220', '+', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-05-20 23:56:48'),
(3, 'stat', 'Cover Pin Codes Pan India', NULL, NULL, NULL, NULL, NULL, NULL, '10', 'K+', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, '2026-05-07 09:04:08', '2026-05-20 23:16:15'),
(4, 'stat', 'Packages Shipped Daily', NULL, NULL, NULL, NULL, NULL, NULL, '25', 'K', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 1, '2026-05-07 09:04:08', '2026-05-20 23:19:10'),
(5, 'stat', 'On-Time Delivery Rate', NULL, NULL, NULL, NULL, NULL, NULL, '99', '%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, 1, '2026-05-07 09:04:08', '2026-05-20 23:17:35'),
(6, 'stat', 'Tracking and Support', NULL, NULL, NULL, NULL, NULL, NULL, '24', '/7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, 1, '2026-05-07 09:04:08', '2026-05-20 23:16:46'),
(8, 'overview', 'Overview for United Couriers', NULL, 'United Worldwide Couriers holds a respectable position, especially in the United States of America and the European sector. We\'ve grown from a company with one mission to a global leader in logistics. Having experience of around three decades, we handle everything from lightweight documents to heavy industrial cargo. Our strength lies in our people. United Couriers is backed by an outstanding team of professionally trained logistics specialists. We work with specialized tracking technology, optimized delivery networks, and strategic partnerships with international carriers. However, we’ve created an ecosystem where your shipment is in the safest possible hands.<br><br>\r\nIn a world where commitments are often made lightly, we take on-time deliveries seriously. Our in-depth knowledge of logistical challenges across major industries helps us to provide dedicated support. And the best part is? We don\'t wait for you to ask about your shipment. We provide regular updates and flag potential delays before they impact you.', 'website_images/1785303640_1779785672_global-network.webp', NULL, NULL, NULL, NULL, NULL, 'Start Shipping', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-07-29 05:40:58'),
(9, 'mission_vision_intro', 'Our Mission and Vision', NULL, 'United Couriers’ mission is to be the logistics partner that businesses depend on, from the moment they hand over a shipment until it reaches its destination. How do we ensure that? We aim to simplify global logistics through dependable service, functional excellence, and customer-attentive solutions for sustainable trust.', 'website_images/1785257535_fa165a90-b622-42cc-8ea7-fe3c168ba42d.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-07-28 11:22:44'),
(10, 'mission', 'Delivering Beyond Expectations', NULL, 'We don’t aim to move packages from point A to point B. It is way more profound and more meaningful than that. Every day, we handle shipments that carry tremendous value. Overall, our mission is to enable your business expansion into new markets, quicker scaling, and stronger customer connections through dependable delivery.', NULL, '<svg width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"white\" stroke-width=\"1.5\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>', NULL, NULL, NULL, NULL, NULL, 'Our Mission', 'blue', NULL, NULL, NULL, NULL, NULL, 2, 1, '2026-05-07 09:04:08', '2026-07-29 05:46:44'),
(11, 'vision', 'Connecting World with Trust and Speed', NULL, 'Our vision extends beyond years of growth. We see a future where United Couriers is synonymous with confidence, speed, and an innovative partner in logistics. A future where our name is the first that comes to mind when someone needs to send something important across a city, a country, or the world.', NULL, '<svg width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"white\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>', NULL, NULL, NULL, NULL, NULL, 'Our Vision', 'purple', NULL, NULL, NULL, NULL, NULL, 3, 1, '2026-05-07 09:04:08', '2026-05-20 23:29:08'),
(12, 'journey_intro', 'A Legacy in Motion', NULL, NULL, 'website_images/1785303703_1784791784_logistic.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '220+', '19000+', 1, 1, '2026-05-07 09:04:08', '2026-07-29 05:41:43'),
(13, 'milestone', 'The Foundation (1997)', NULL, 'We opened our first head office in Dehi and started the journey for UWC.', NULL, '<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"2\"><path d=\"M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5\"/></svg>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'card-purple', NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-07-23 01:32:11'),
(14, 'milestone', 'Hyper Growth (2005)', NULL, 'We expanded to 15+ cities in India and many international hubs (the USA, the UK, and Germany). Our partner network grew by 400%, becoming the preferred courier for small, medium, and top-level exporters in the country.', NULL, '<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'card-green', NULL, NULL, NULL, 2, 1, '2026-05-07 09:04:08', '2026-05-20 23:31:08'),
(15, 'milestone', 'Tech First (2021)', NULL, 'Introduced our portal and electronic booking platform for all. Uplifted all our e-commerce sellers across the country with real-time AI tracking and automated integration with worldwide marketplaces.', NULL, '<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'card-blue', NULL, NULL, NULL, 3, 1, '2026-05-07 09:04:08', '2026-05-20 23:31:34'),
(16, 'milestone', 'Global Reach (2023)', NULL, 'Increased our network and team by 2X in the last decade to become a recognisable and profitable organization all around the world.', NULL, '<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'card-orange', NULL, NULL, NULL, 4, 1, '2026-05-07 09:04:08', '2026-05-20 23:31:53'),
(17, 'milestone', 'Sustainable Future (2025)', NULL, 'Coordinating and committing to 100% EV delivery with all our last-mile partners and pioneering sustainable and eco-friendly packaging for all corporate partners across the globe.', NULL, '<svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\"><path d=\"M12 19V5M5 12l7-7 7 7\"/></svg>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'card-blue', NULL, NULL, NULL, 5, 1, '2026-05-07 09:04:08', '2026-05-20 23:32:29'),
(18, 'testimonial', 'Shelly Kapoor', NULL, 'Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.', 'website_images/review-1.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(19, 'testimonial', 'Vansh Agarwal', NULL, 'Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real‑time updates and guidance.', 'website_images/review-2.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 2, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(20, 'testimonial', 'Rahul Mehta', NULL, 'Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.', 'website_images/review-3.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 3, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(21, 'testimonial', 'Anjali Sharma', NULL, 'Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.', 'website_images/review-4.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 4, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(22, 'testimonial', 'Karan Singh', NULL, 'Professional and efficient team handled my bulk shipments perfectly, ensuring timely delivery, careful handling, and a completely hassle‑free logistics experience.', 'website_images/review-5.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 5, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(23, 'testimonial', 'Vinay Verma', NULL, 'United Worldwide Couriers delivered my international parcel quickly and safely, with smooth handling and excellent service throughout the entire process.', 'website_images/review-6.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, 6, 1, '2026-05-07 09:04:08', '2026-05-20 10:23:40'),
(38, 'partner', 'FedEx', NULL, NULL, 'https://1000logos.net/wp-content/uploads/2021/04/Fedex-logo.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-05-07 09:04:08'),
(39, 'partner', 'UPS', NULL, NULL, 'https://www.ups.com/webassets/icons/logo.svg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, '2026-05-07 09:04:08', '2026-05-07 09:04:08'),
(40, 'partner', 'USPS', NULL, NULL, 'https://www.usps.com/global-elements/header/images/utility-header/logo-sb.svg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 1, '2026-05-07 09:04:08', '2026-05-07 09:04:08'),
(41, 'partner', 'TNT', NULL, NULL, 'https://www.tnt.com/dam/tnt_express_media/en_gb/images/ChoosingTNT/TNT-Logo-edt.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, 1, '2026-05-07 09:04:08', '2026-05-07 09:04:08'),
(42, 'partner', 'Aramex', NULL, NULL, 'https://dotcomaramexprod.blob.core.windows.net/default/docs/default-source/logo/aramex-logo-english.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, 1, '2026-05-07 09:04:08', '2026-05-07 09:04:08'),
(43, 'newsletter_cta', 'Nevers miss a shipment update!', NULL, 'Subscribe for smart logistics tips, real‑time updates, and exclusive offers to simplify your shipping experience.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-05-07 09:04:08', '2026-05-07 09:48:38');
