INSERT INTO `shipping_rate_calculator_page` (`id`, `section_type`, `title`, `subtitle`, `description`, `image`, `icon_svg`, `link`, `display_order`, `page_badge_text`, `page_button_text`, `page_tag`, `page_label`, `page_placeholder`, `page_icon_class`, `status`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'Shipping <span class=\"moving-gradient-text\">Rate Calculator</span>', NULL, 'Get accurate, all-inclusive rates in seconds — no hidden charges, no guesswork.', 'website_images/1785305944_shipping_rate_calculator.png', NULL, NULL, 0, 'Free Tool · Instant Results', NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-07-29 06:19:16'),
(2, 'features', 'Enter Pickup Details', NULL, 'Add pickup pincode and shipment information to begin calculating the courier charges for your international destinations.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-location-dot', 1, '2026-05-26 00:30:17', '2026-07-29 06:20:02'),
(3, 'features', 'Select Destination Country', NULL, 'Choose the delivery pincode with accurate weight to get instant rates with economy and express delivery options.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-earth-asia', 1, '2026-05-26 00:30:17', '2026-07-28 13:30:58'),
(4, 'features', 'Get Shipping Rate Instantly', NULL, 'View estimated courier pricing instantly with transparent charges, faster transit options, and no hidden costs at checkout.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, 'fa-solid fa-money-bill-wave', 1, '2026-05-26 00:30:17', '2026-07-28 13:31:37'),
(5, 'features_heading', 'Understanding Rate Calculator', NULL, 'Rate calculators help estimate accurate shipping charges before booking shipments.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-07-29 06:20:38'),
(6, 'track_cta', 'Track any shipment in real-time', NULL, 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 0, '● LIVE TRACKING', 'Track Shipment →', NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(7, 'testimonials_header', 'Trusted by the Brands You Trust', NULL, 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(8, 'faq_header', 'Frequently Asked Questions', 'Common Questions', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(9, 'faq', 'How do I get started?', NULL, 'To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(10, 'faq', 'How does United Worldwide Couriers meet your shipping and logistics needs?', NULL, 'To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(11, 'faq', 'What packaging standards should we follow for shipping?', NULL, 'We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \"Fragile\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(12, 'faq', 'How do we calculate cost?1', NULL, 'The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.', NULL, NULL, NULL, 4, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-07-29 06:19:32'),
(13, 'faq', 'Will I be notified about my shipment status?', NULL, 'Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.', NULL, NULL, NULL, 5, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(14, 'faq', 'Does United Worldwide Couriers handle bulk or commercial shipments?', NULL, 'Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.', NULL, NULL, NULL, 6, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(15, 'faq', 'Can I schedule a pickup for my shipment?', NULL, 'Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.', NULL, NULL, NULL, 7, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(16, 'faq', 'How can I track my shipment?', NULL, 'Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.', NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(17, 'faq', 'Will my package be picked up by the United Worldwide Couriers team only?', NULL, 'It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.', NULL, NULL, NULL, 9, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(18, 'faq', 'Do you provide customs clearance support?', NULL, 'Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.', NULL, NULL, NULL, 10, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(19, 'faq', 'What happens if my shipment is delayed or stuck?', NULL, 'First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.', NULL, NULL, NULL, 11, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17'),
(20, 'faq_contact_sidebar', 'Need personalized help?', NULL, 'Our logistics experts are available 24/7 to assist your requirements.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-05-26 00:30:17', '2026-05-26 00:30:17');
