INSERT INTO `volumetric_calculator_page` (`id`, `page`, `section`, `data_title`, `data_description`, `data_icon`, `data_image`, `data_link`, `data_button_text`, `data_extra`, `data`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'volumetric-calculator', 'hero', 'Volumetric <span class=\"moving-gradient-text\">Weight Calculator</span>', 'Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.', NULL, 'assets/images/1785306141_volumetric-weight.webp', NULL, 'Calculate Now', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_url\":\"#\"}', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"title\":\"Volumetric <span class=\\\"moving-gradient-text\\\">Weight Calculator<\\/span>\",\"description\":\"Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.\",\"button_text\":\"Calculate Now\",\"button_url\":\"#\",\"image\":\"assets\\/images\\/1785306141_volumetric-weight.webp\"}', 1, 1, '2026-05-11 23:34:05', '2026-07-29 06:23:06'),
(2, 'volumetric-calculator', 'features_header', 'Understanding volumetric weight', 'Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.', NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Understanding volumetric weight\",\"description\":\"Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.\"}', 2, 1, '2026-05-11 23:34:05', '2026-07-29 06:26:36'),
(3, 'volumetric-calculator', 'features', 'Measure all three dimensions', 'Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.', 'fa-solid fa-ruler', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-ruler\"}', '{\"icon_class\":\"fa-solid fa-ruler\",\"title\":\"Measure all three dimensions\",\"description\":\"Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.\"}', 3, 1, '2026-05-11 23:34:05', '2026-07-28 13:24:38'),
(4, 'volumetric-calculator', 'features', 'Apply the divisor formula', 'Multiply length × width × height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.', 'fa-solid fa-divide', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-divide\"}', '{\"icon_class\":\"fa-solid fa-divide\",\"title\":\"Apply the divisor formula\",\"description\":\"Multiply length \\u00d7 width \\u00d7 height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.\"}', 4, 1, '2026-05-11 23:34:05', '2026-07-28 13:25:12'),
(5, 'volumetric-calculator', 'features', 'Compare with actual weight', 'While many charge whichever is higher, actual or volumetric weight. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.', 'fa-solid fa-scale-balanced', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-scale-balanced\"}', '{\"icon_class\":\"fa-solid fa-scale-balanced\",\"title\":\"Compare with actual weight\",\"description\":\"While many charge whichever is higher, actual or volumetric weight. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.\"}', 5, 1, '2026-05-11 23:34:05', '2026-07-28 13:25:52'),
(6, 'volumetric-calculator', 'track_cta', 'Track any shipment in real-times', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 'Track Shipment →', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"button_url\":null}', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"title\":\"Track any shipment in real-times\",\"description\":\"Get live updates across all major carriers \\u2014 end-to-end visibility from pickup to delivery for every order you export worldwide.\",\"button_text\":\"Track Shipment \\u2192\",\"button_url\":null}', 6, 1, '2026-05-11 23:34:05', '2026-05-12 13:17:50'),
