(8, 'overview', 'overview_main', '{\"title\":\"Store - Track - Ship - Repeat\",\"paragraphs\":\"United Worldwide Couriers offers an exceptional Express Air Freight service built for B2B enterprises, e-commerce businesses, and time-critical international shipments. We operate an end-to-end ecosystem from collection to customs clearance to last-mile delivery all under one roof. Our services span air freight to over 220 countries, including door-to-door personal import pickups and full freight-forwarding with seamless documentation. Each shipment is handled by a dedicated logistics specialist and backed by real-time tracking.\",\"image\":\"assets\\/images\\/1785314455_united-warehouse.webp\",\"list_items\":[\"Priority loading on partner airline networks across 6 continents\",\"Full customs brokerage with pre-clearance documentation support\",\"Dedicated account manager and 24\\/7 live shipment support\",\"Door-to-door delivery with real-time GPS tracking portal\",\"Fulfilment services\",\"returns management\",\"and COD options\"],\"button_text\":\"Book Shipments\",\"button_url\":\"#\"}', NULL, NULL, NULL, NULL, 'Book Shipments', '#', NULL, NULL, 'United Worldwide Couriers offers an exceptional Express Air Freight service built for B2B enterprises, e-commerce businesses, and time-critical international shipments. We operate an end-to-end ecosystem from collection to customs clearance to last-mile delivery all under one roof. Our services span air freight to over 220 countries, including door-to-door personal import pickups and full freight-forwarding with seamless documentation. Each shipment is handled by a dedicated logistics specialist and backed by real-time tracking.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Priority loading on partner airline networks across 6 continents\nFull customs brokerage with pre-clearance documentation support\nDedicated account manager and 24/7 live shipment support\nDoor-to-door delivery with real-time GPS tracking portal\nFulfilment services\nreturns management\nand COD options', NULL, '{\"title\":\"Store. Manage. Fulfil\\u2014Smarter from The USA\",\"image\":\"images\\/map-pattern.png\"}', 12, 1, '2026-05-13 22:11:13', '2026-07-29 08:40:55'),
(9, 'features', 'features_header', '{\"title\":\"Transforming Inventory Management Into Your Advantage\",\"subtitle\":\"Powering your business with cutting-edge logistics technology and unmatched service quality.\",\"description\":null,\"paragraphs\":\"Every feature is designed to give your business a competitive edge \\u2014 speed, transparency, and reliability, every single shipment. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Powering your business with cutting-edge logistics technology and unmatched service quality.', 'Every feature is designed to give your business a competitive edge — speed, transparency, and reliability, every single shipment. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"What Makes Our E-commerce Logistics Stand Out\"}', 13, 1, '2026-05-13 22:11:13', '2026-07-28 13:15:55'),
(10, 'features', 'feature_tracking', '{\"subtitle\":\"Real-Time Tracking\",\"paragraphs\":\"Monitor your shipment at every checkpoint \\u2014 from pickup to customs to final-mile \\u2014 through our live dashboard and SMS alerts.\",\"icon_svg\":\"<i class=\\\"fas fa-satellite\\\"><\\/i>\",\"icon_class\":\"fi-blue\"}', '<i class=\"fas fa-satellite\"></i>', 'fi-blue', NULL, NULL, NULL, NULL, NULL, 'Real-Time Tracking', 'Monitor your shipment at every checkpoint — from pickup to customs to final-mile — through our live dashboard and SMS alerts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14, 1, '2026-05-13 22:11:13', '2026-07-28 12:55:26'),
(11, 'features', 'feature_temperature', '{\"subtitle\":\"Automated Stock Optimization\",\"paragraphs\":\"Control overstock and stockouts with smart demand-based inventory management.\",\"icon_svg\":\"<i class=\\\"fas fa-thermometer-half\\\"><\\/i>\",\"icon_class\":\"fi-orange\"}', '<i class=\"fas fa-thermometer-half\"></i>', 'fi-orange', NULL, NULL, NULL, NULL, NULL, 'Automated Stock Optimization', 'Control overstock and stockouts with smart demand-based inventory management.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15, 1, '2026-05-13 22:11:13', '2026-05-30 04:13:25'),
(12, 'features', 'feature_support', '{\"subtitle\":\"Monitoring and Security\",\"paragraphs\":\"24\\/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.\",\"icon_svg\":\"<i class=\\\"fas fa-headset\\\"><\\/i>\",\"icon_class\":\"fi-navy\"}', '<i class=\"fas fa-headset\"></i>', 'fi-navy', NULL, NULL, NULL, NULL, NULL, 'Monitoring and Security', '24/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 1, '2026-05-13 22:11:13', '2026-05-30 04:14:43'),
(13, 'features', 'feature_eco', '{\"subtitle\":\"Multi-Channel Inclusion\",\"paragraphs\":\"Businesses can manage their inventory for all channels like B2B, D2C and e-commerce.\",\"icon_svg\":\"<i class=\\\"fas fa-leaf\\\"><\\/i>\",\"icon_class\":\"fi-green\"}', '<i class=\"fas fa-leaf\"></i>', 'fi-green', NULL, NULL, NULL, NULL, NULL, 'Multi-Channel Inclusion', 'Businesses can manage their inventory for all channels like B2B, D2C and e-commerce.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, 1, '2026-05-13 22:11:13', '2026-05-30 04:15:14'),
(14, 'testimonials', 'testimonials_header', '{\"title\":\"Trusted by the Brands You Trust\",\"paragraphs\":\"Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Trusted by the Brands You Trust\"}', 18, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(15, 'testimonials', 'testimonial_1', '{\"subtitle\":\"Shelly Kapoor\",\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shelly Kapoor', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\"}', 19, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(16, 'testimonials', 'testimonial_2', '{\"subtitle\":\"Vansh Agarwal\",\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vansh Agarwal', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\"}', 20, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(17, 'testimonials', 'testimonial_3', '{\"subtitle\":\"Rahul Mehta\",\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rahul Mehta', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\"}', 21, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(18, 'testimonials', 'testimonial_4', '{\"subtitle\":\"Anjali Sharma\",\"description\":\"Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.\",\"image\":\"images\\/review-4.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anjali Sharma', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.\",\"image\":\"images\\/review-4.png\"}', 22, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(20, 'testimonials', 'testimonial_6', '{\"subtitle\":\"Vinay Verma\",\"description\":\"United Worldwide Couriers delivered my international parcel quickly and safely, with smooth handling and excellent service throughout the entire process.\",\"image\":\"images\\/review-5.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vinay Verma', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"United Worldwide Couriers delivered my international parcel quickly and safely, with smooth handling and excellent service throughout the entire process.\",\"image\":\"images\\/review-5.png\"}', 24, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(21, 'testimonials', 'testimonial_7', '{\"subtitle\":\"Shelly Kapoor\",\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-6.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shelly Kapoor', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-6.png\"}', 25, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(22, 'testimonials', 'testimonial_8', '{\"subtitle\":\"Vansh Agarwal\",\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-7.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vansh Agarwal', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-7.png\"}', 26, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(34, 'cta', 'cta_main', '{\"title\":\"Ready to Optimize Your Storage?\",\"subtitle\":\"Get in touch with our team to discuss your warehousing needs\",\"button_text\":\"Contact Us\",\"button_url\":\"\\/contact-us\"}', NULL, NULL, NULL, NULL, 'Contact Us', '/contact-us', NULL, 'Get in touch with our team to discuss your warehousing needs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Ready to Optimize Your Storage?\",\"subtitle\":\"Get in touch with our team to discuss your warehousing needs\"}', 38, 1, '2026-05-13 22:11:13', '2026-05-30 03:54:19'),
(36, 'hero', 'hero_main', '{\"title\":\"Warehousing Solutions\",\"subtitle\":\"Secure Storage for Your Business Needs\",\"paragraphs\":\"Our state-of-the-art warehousing facilities provide secure, climate-controlled storage solutions tailored to your business requirements. With advanced inventory management systems and 24\\/7 monitoring, we ensure your goods are safe and accessible whenever you need them.\",\"badge_text\":\"Premium Storage\",\"button_text\":\"Get Started\",\"button_url\":\"\\/contact-us\",\"image\":\"assets\\/images\\/1785314376_warehousing.webp\",\"list_items\":[\"24\\u201372 Hr Delivery\",\"Fully Insured\",\"220+ Countries\"]}', NULL, NULL, NULL, 'Premium Storage', 'Get Started', '/contact-us', NULL, 'Secure Storage for Your Business Needs', 'Our state-of-the-art warehousing facilities provide secure, climate-controlled storage solutions tailored to your business requirements. With advanced inventory management systems and 24/7 monitoring, we ensure your goods are safe and accessible whenever you need them.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '24–72 Hr Delivery\nFully Insured\n220+ Countries', NULL, '{\"title\":\"Warehousing Solutions\",\"image\":\"images\\/warehousing.webp\"}', 1, 1, '2026-05-30 03:54:19', '2026-07-29 08:39:37');
